SELECT p.id AS paper_id, m.source, m.delivery_status, COUNT(*) AS n, MIN(m.price) AS min_px, MAX(m.price) AS max_px, MIN(m.observed_at) AS first_obs, MAX(m.observed_at) AS last_obs FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event m ON m.symbol = p.symbol AND m.observed_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.closed_at + INTERVAL 5 SECOND WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, m.source, m.delivery_status ORDER BY p.id;